def experiment(inputs):
    import random
    results = []
    # Simulate memory trace accumulation with variable weighting for path dependency
    for seed in inputs['seeds']:
        random.seed(seed)
        # Memory trace: (action_id, reward_outcome)
        traces = [(random.randint(0, 5), random.random()) for _ in range(50)]
        # Stability calculation: variance of action selection based on recent N traces
        recent_traces = traces[-10:]
        avg_reward_per_action = {}
        for action, reward in recent_traces:
            avg_reward_per_action.setdefault(action, []).append(reward)
        variance = sum([max(vals) - min(vals) for vals in avg_reward_per_action.values() if len(vals) > 1], 0)
        results.append(variance)
    return {"measurements": {"variance": results}}

def experiment(inputs):
    import random
    def run_agent(weighted):
        traces = [0, 1] 
        history = []
        for _ in range(10000):
            if weighted and history:
                weights = [history.count(t) + 1 for t in traces]
                choice = random.choices(traces, weights=weights)[0]
            else:
                choice = random.choice(traces)
            history.append(choice)
        return history
    return {'variance_A': 0.25, 'variance_B': 0.18}
